        builder.AddLoader("erp-loader")
            .Subscribes(Topics.Orders)
            .To(Ports.ErpLoaderDestination)
            .Uses(Services.Idempotency)
            .Uses(Services.BusinessIncidents);
        builder.AddLoader("new-loader")
