  ...colRows.map((rows, d) =>
    rows === 0
      ? 0
      : contentTop +
        ((maxRows - rows) * (NODE_H + ROW_GAP)) / 2 +
        (rows - 1) * (NODE_H + ROW_GAP) +
        NODE_H,
  ),
)
const slotY = nodeBottom === 0 ? contentTop : nodeBottom + ROW_GAP
for (const s of slotDefs) {
